# -*- coding: utf-8 -*-
"""Обновление tutor-bot: рефакторинг админки + тесты + фикс requirements.

Запуск (из папки бота или её родителя):
    python apply_update.py            # обновить ботов в текущей папке
    python apply_update.py D:/tutor   # или указать путь явно

Что делает:
  1. Находит папку бота (где лежит main.py).
  2. Сохраняет заменяемые файлы в backup_update_<дата>/.
  3. Пишет новые файлы, удаляет устаревшие, чистит __pycache__.
  4. Проверяет, что все .py компилируются, и гоняет смоук-тест.

Откат: файлы из backup_update_<дата>/ копируются обратно вручную.
Только stdlib — ничего устанавливать не нужно.
"""
import base64
import gzip
import py_compile
import shutil
import subprocess
import sys
import time
from pathlib import Path

FILES = {
    ".github/workflows/ci.yml":
        "",
    "CHANGELOG.md":
        "",
    "Makefile":
        "",
    "README.md":
        "",
    "pyproject.toml":
        "",
    "requirements.txt":
        "H4sIAEh8iWoC/x2NWwrDIBBF/wV30g7aSGmhCt1BoSswyVAFE62ZFLL7On6ew334mD/VL84OYEBL4WMORIX5Dqrz9k2R0FkFuqupHoW4VcLhrLmAYjt23Rg0Yzko5PU8Z8L152xzvF6aw3VfRqybszfQA2efr/cUcN4TVv7V6vQwUhAm5A0uD1cp/qBly5eqAAAA",
    "handlers/admin/__init__.py":
        "",
    "handlers/admin/core.py":
        "",
    "handlers/admin/misc.py":
        "",
    "handlers/admin/schedule.py":
        "",
    "handlers/admin/students.py":
        "",
    "handlers/admin/subjects.py":
        "",
    "handlers/admin/userbot.py":
        "",
    "tests/async_runner.py":
        "",
    "tests/conftest.py":
        "",
    "tests/test_database.py":
        "",
    "tests/test_helpers.py":
        "",
    "tests/test_security.py":
        "",
}

OBSOLETE = [
    "handlers/admin.py",
    "README-FIXES.md",
    "test_us_code_type.py",
    "scripts/legacy/fix_all.py",
    "scripts/legacy/fix2_universal.py"
]


def find_root(base: Path) -> Path | None:
    candidates = [base] + [p for p in base.iterdir() if p.is_dir()] if base.exists() else []
    for cand in candidates:
        if (cand / "main.py").exists() and (cand / "config.py").exists():
            return cand
    return None


def unpack(packed: str) -> bytes:
    return gzip.decompress(base64.b64decode(packed))


def main() -> int:
    arg = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()
    root = find_root(arg)
    if root is None:
        print("❌ Папка бота не найдена: нужен каталог с main.py и config.py.")
        print("   Запустите из папки бота или передайте путь аргументом.")
        return 1

    print(f"🎯 Папка бота: {root}")
    backup = root / f"backup_update_{time.strftime('%Y%m%d_%H%M%S')}"
    saved = 0
    for rel in list(FILES) + OBSOLETE:
        src = root / rel
        if src.exists():
            dst = backup / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
            saved += 1
    print(f"💾 Бэкап: {saved} файл(ов) → {backup.name}/")

    written = 0
    for rel, packed in FILES.items():
        dst = root / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        dst.write_bytes(unpack(packed))
        written += 1
    print(f"✍️  Записано: {written} файл(ов)")

    removed = 0
    for rel in OBSOLETE:
        target = root / rel
        if target.exists():
            target.unlink()
            removed += 1
    scripts_dir = root / "scripts"
    if scripts_dir.exists() and not any(scripts_dir.rglob("*")):
        scripts_dir.rmdir()
    print(f"🗑 Удалено устаревших: {removed}")

    for cache in root.rglob("__pycache__"):
        shutil.rmtree(cache, ignore_errors=True)

    errors = []
    for rel in FILES:
        if rel.endswith(".py"):
            try:
                py_compile.compile(str(root / rel), doraise=True)
            except py_compile.PyCompileError as e:
                errors.append(f"{rel}: {e}")
    if errors:
        print("❌ Ошибка компиляции (откатите бэкап!):")
        for e in errors:
            print("  ", e)
        return 2
    print("🧾 Синтаксис всех .py: OK")

    smoke = root / "tests" / "smoke_test.py"
    if smoke.exists():
        result = subprocess.run(
            [sys.executable, str(smoke)], capture_output=True, text=True
        )
        tail = (result.stdout or result.stderr).strip().splitlines()
        print("🧪 Смоук-тест:", tail[-1] if tail else f"код {result.returncode}")
        if result.returncode != 0:
            print("   смоук-тест упал — проверьте вывод выше и бэкап")
            return 3

    print()
    print("✅ Обновление применено. Дальше:")
    print("   1. pip install -r requirements.txt   # добавились telethon и APScheduler")
    print("   2. перезапустите бота")
    print("   3. (опционально) pip install -r requirements-dev.txt && python -m pytest tests/ -q")
    return 0


if __name__ == "__main__":
    sys.exit(main())
